17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.validation.DisposableEmailException;
36	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
37	import org.springframework.samples.petclinic.rest.validation.FutureRegistrationDateException;
38	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
39	import org.springframework.samples.petclinic.rest.validation.InvalidTelephoneException;
40	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
41	import org.springframework.security.access.AccessDeniedException;
42	import org.springframework.validation.BindingResult;
43	import org.springframework.validation.FieldError;
44	import org.springframework.web.bind.MethodArgumentNotValidException;
45	import org.springframework.web.bind.annotation.ControllerAdvice;
46	import org.springframework.web.bind.annotation.ExceptionHandler;
47	import org.springframework.web.bind.annotation.ResponseBody;
48	
49	/**
50	 * Global Exception handler for REST controllers.
51	 * <p>
52	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
53	 *
54	 * @author Vitaliy Fedoriv
55	 * @author Alexander Dudkin
56	 */
57	@ControllerAdvice
58	public class ExceptionControllerAdvice {
59	
60	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
61	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
62	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
63	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
64	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity already exists";
65	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has already reached its maximum number of owners";
66	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners that may be registered today has already been reached";
67	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The registration date must not be later than the server date";
68	    private static final String ERROR_DISPOSABLE_EMAIL = "The owner's email domain is not accepted";
69	
70	    /**
71	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
72	     * class.
73	     *
74	     * @param e     Object referring to the thrown exception.
75	     * @param status HTTP response status.
76	     * @param url URL request.
77	     */
78	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
79	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
80	        problemDetail.setType(URI.create(url.toString()));
81	        problemDetail.setTitle(e.getClass().getSimpleName());
82	        problemDetail.setDetail(detail);
83	        problemDetail.setProperty("timestamp", Instant.now());
84	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
85	        return problemDetail;
86	    }
87	
88	    /**
89	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
90	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
91	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
92	     * would catch it and report an authorization failure as a 500.
93	     *
94	     * @param e The {@link AccessDeniedException} to propagate
95	     * @throws AccessDeniedException always
96	     */
97	    @ExceptionHandler(AccessDeniedException.class)
98	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
99	        throw e;
100	    }
101	
102	    /**
103	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
104	     *
105	     * @param e The {@link Exception} to be handled
106	     * @param request {@link HttpServletRequest} object referring to the current request.
107	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
108	     */
109	    @ExceptionHandler(Exception.class)
110	    @ResponseBody
111	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
112	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
113	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
114	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
115	        return ResponseEntity.status(status).body(detail);
116	    }
117	
118	    /**
119	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
120	     * method returns a 404 Not Found status if an entity does not exist.
121	     *
122	     * @param e The {@link DataIntegrityViolationException} to be handled
123	     * @param request {@link HttpServletRequest} object referring to the current request.
124	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
125	     */
126	    @ExceptionHandler(DataIntegrityViolationException.class)
127	    @ResponseBody
128	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
129	        logger.warn("Data integrity violation at {} {}: {}",
130	            request.getMethod(),
131	            request.getRequestURI(),
132	            e.getMessage());
133	        logger.debug("Data integrity violation stacktrace", e);
134	        HttpStatus status = HttpStatus.NOT_FOUND;
135	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
136	        return ResponseEntity.status(status).body(detail);
137	    }
138	
139	    /**
140	     * Handles exception thrown by Bean Validation on controller methods parameters
141	     *
142	     * @param e The {@link MethodArgumentNotValidException} to be handled
143	     * @param request {@link HttpServletRequest} object referring to the current request.
144	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
145	     */
146	    @ExceptionHandler(MethodArgumentNotValidException.class)
147	    @ResponseBody
148	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
149	        HttpStatus status = HttpStatus.BAD_REQUEST;
150	        BindingErrorsResponse errors = new BindingErrorsResponse();
151	        BindingResult bindingResult = e.getBindingResult();
152	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
153	        if (bindingResult.hasErrors()) {
154	            errors.addAllErrors(bindingResult);
155	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
156	                .map(fieldError -> {
157	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
158	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
159	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
160	                        fieldError.getField(),
161	                        defaultMessage,
162	                        rejectedValue);
163	                    return new ValidationMessageDto(message)
164	                        .putAdditionalProperty("field", fieldError.getField())
165	                        .putAdditionalProperty("rejectedValue", rejectedValue)
166	                        .putAdditionalProperty("defaultMessage", defaultMessage);
167	                })
168	                .toList();
169	            logger.debug("Validation error at {} {}: {}",
170	                request.getMethod(),
171	                request.getRequestURI(),
172	                bindingResult.getFieldErrors());
173	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
174	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
175	                .map(FieldError::getField)
176	                .distinct()
177	                .toList();
178	            detail.setProperty("errors", invalidFields);
179	            return ResponseEntity.status(status).body(detail);
180	        }
181	        return ResponseEntity.status(status).body(detail);
182	    }
183	
184	    /**
185	     * Handles {@link MissingOwnerFieldsException} raised when a request to create or update an owner
186	     * omits one or more mandatory fields, returning a 400 Bad Request whose {@code errors} array lists
187	     * the name of each missing field.
188	     *
189	     * @param e The {@link MissingOwnerFieldsException} to be handled
190	     * @param request {@link HttpServletRequest} object referring to the current request.
191	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
192	     */
193	    @ExceptionHandler(MissingOwnerFieldsException.class)
194	    @ResponseBody
195	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
196	        HttpStatus status = HttpStatus.BAD_REQUEST;
197	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
198	        detail.setProperty("errors", e.getFields());
199	        return ResponseEntity.status(status).body(detail);
200	    }
201	
202	    /**
203	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number cannot be
204	     * converted to a valid E.164 value, returning a 400 Bad Request.
205	     *
206	     * @param e The {@link InvalidTelephoneException} to be handled
207	     * @param request {@link HttpServletRequest} object referring to the current request.
208	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
209	     */
210	    @ExceptionHandler(InvalidTelephoneException.class)
211	    @ResponseBody
212	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
213	        HttpStatus status = HttpStatus.BAD_REQUEST;
214	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
215	        detail.setProperty("errors", List.of("telephone"));
216	        return ResponseEntity.status(status).body(detail);
217	    }
218	
219	    /**
220	     * Handles {@link InvalidPostcodeException} raised when a supplied postcode is out of range for
221	     * its city's region, returning a 400 Bad Request.
222	     *
223	     * @param e The {@link InvalidPostcodeException} to be handled
224	     * @param request {@link HttpServletRequest} object referring to the current request.
225	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
226	     */
227	    @ExceptionHandler(InvalidPostcodeException.class)
228	    @ResponseBody
229	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
230	        HttpStatus status = HttpStatus.BAD_REQUEST;
231	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
232	        detail.setProperty("errors", List.of("postcode"));
233	        return ResponseEntity.status(status).body(detail);
234	    }
235	
236	    /**
237	     * Handles {@link DuplicateIdentityException} raised when a new owner's identity key (the digest
238	     * of normalized telephone, email and the Soundex code of the last name) exactly matches that of
239	     * an existing owner, returning a 409 Conflict.
240	     *
241	     * @param e The {@link DuplicateIdentityException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
244	     */
245	    /**
246	     * Handles {@link FutureRegistrationDateException} raised when a supplied registration date is
247	     * later than the server's current date, returning a 400 Bad Request.
248	     *
249	     * @param e The {@link FutureRegistrationDateException} to be handled
250	     * @param request {@link HttpServletRequest} object referring to the current request.
251	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
252	     */
253	    @ExceptionHandler(FutureRegistrationDateException.class)
254	    @ResponseBody
255	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
256	        HttpStatus status = HttpStatus.BAD_REQUEST;
257	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_FUTURE_REGISTRATION_DATE);
258	        detail.setProperty("errors", List.of("registrationDate"));
259	        return ResponseEntity.status(status).body(detail);
260	    }
261	
262	    /**
263	     * Handles {@link DisposableEmailException} raised when the owner's email domain is on the
264	     * disposable-domain blocklist, returning a 400 Bad Request.
265	     *
266	     * @param e The {@link DisposableEmailException} to be handled
267	     * @param request {@link HttpServletRequest} object referring to the current request.
268	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
269	     */
270	    @ExceptionHandler(DisposableEmailException.class)
271	    @ResponseBody
272	    public ResponseEntity<ProblemDetail> handleDisposableEmailException(DisposableEmailException e, HttpServletRequest request) {
273	        HttpStatus status = HttpStatus.BAD_REQUEST;
274	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DISPOSABLE_EMAIL);
275	        detail.setProperty("errors", List.of("email"));
276	        return ResponseEntity.status(status).body(detail);
277	    }
278	
279	    @ExceptionHandler(DuplicateIdentityException.class)
280	    @ResponseBody
281	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
282	        HttpStatus status = HttpStatus.CONFLICT;
283	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
284	        detail.setProperty("errors", List.of("identityKey"));
285	        return ResponseEntity.status(status).body(detail);
286	    }
287	
288	    /**
289	     * Handles {@link CityCapacityExceededException} raised when a new owner is submitted for a city
290	     * that already holds the maximum number of owners, returning a 409 Conflict.
291	     *
292	     * @param e The {@link CityCapacityExceededException} to be handled
293	     * @param request {@link HttpServletRequest} object referring to the current request.
294	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
295	     */
296	    @ExceptionHandler(CityCapacityExceededException.class)
297	    @ResponseBody
298	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
299	        HttpStatus status = HttpStatus.CONFLICT;
300	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
301	        detail.setProperty("errors", List.of("city"));
302	        return ResponseEntity.status(status).body(detail);
303	    }
304	
305	    /**
306	     * Handles {@link DailyOwnerLimitExceededException} raised when the maximum number of owners
307	     * allowed to be registered on a single day has already been reached, returning a 429 Too Many
308	     * Requests.
309	     *
310	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
311	     * @param request {@link HttpServletRequest} object referring to the current request.
312	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
313	     */
314	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
315	    @ResponseBody
316	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
317	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
318	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_REACHED);
319	        detail.setProperty("errors", List.of("registrationDate"));
320	        return ResponseEntity.status(status).body(detail);
321	    }
322	
323	}
